{"code": "const TEST_FILE = 'test-environment/test-customers.json';
const JSON_HEADERS = { 'content-type': 'application/json; charset=utf-8', 'Access-Control-Allow-Origin': '*' };
const BASE = '/voice/v1/';
const SERVICES = ['cards.list', 'cards.balance', 'statement.week.get', 'statement.week.decide', 'statement.week.change', 'contact.email.get', 'statement.pdf.send'];

function jsonResponse(body, status) {
  return new Response(JSON.stringify(body), { status: status || 200, headers: JSON_HEADERS });
}

function newGuid() {
  const hex = '0123456789abcdef';
  let s = '';
  for (let i = 0; i < 32; i++) s += hex[Math.floor(Math.random() * 16)];
  return s;
}

function errorBody(code, message, type, rootCause) {
  const guid = newGuid();
  return {
    result: {
      guid: guid,
      returnCode: code,
      messageText: message,
      code: code,
      message: message,
      type: type,
      details: { guid: guid, rootCause: rootCause, errorOrigin: 'ivr-gateway-test:ivr-channel-v0' }
    }
  };
}

function invalidArgs(message) {
  return jsonResponse(errorBody('INVALID_ARGUMENTS_ERROR', message, 'ERROR', 'InvalidArgumentsException'), 400);
}

function technicalError() {
  return jsonResponse(errorBody('FBE00099', 'Teknik hata: ABORTED: ', 'ERROR', 'TechnicalError'), 500);
}

const NOT_FOUND = {
  'cards.list': ['FB_IVR_CHANNEL_102', 'Müşteriye ait geçerli kart bilgisi bulunamadı.', 'NotFoundException'],
  'cards.balance': ['FB_IVR_CHANNEL_120', 'Kart bakiye servisi hatası: kart bulunamadı', 'NotFoundException'],
  'statement.week.get': ['FB_IVR_CHANNEL_121', 'Kart bulunamadı', 'NotFoundException'],
  'statement.pdf.send': ['FB_IVR_CHANNEL_107', 'Pdf dokümanı bulunamadı', 'com.freyabank.ivrgateway.ivrchannel.rest.exception.NotFoundException']
};

function notFound(service, fallbackMessage) {
  const nf = NOT_FOUND[service];
  if (nf) return jsonResponse(errorBody(nf[0], nf[1], 'WARNING', nf[2]), 404);
  return invalidArgs(fallbackMessage || 'record not found');
}

function isTemplate(v) {
  return typeof v === 'string' && (v.trim().startsWith('{{') || v.trim().startsWith('%7B%7B'));
}

function isEmpty(v) {
  return v === undefined || v === null || (typeof v === 'string' && v.trim() === '');
}

function norm(v) {
  if (v === undefined || v === null) return '';
  return String(v).trim();
}

function normWeek(v) {
  const s = norm(v);
  if (/^\d+(\.0+)?$/.test(s)) return String(parseInt(s, 10));
  return s;
}

function getData() {
  const d = (typeof DATA !== 'undefined' && DATA) ? DATA[TEST_FILE] : null;
  return d || {};
}

function customers() {
  const d = getData();
  if (Array.isArray(d)) return d;
  if (Array.isArray(d.customers)) return d.customers;
  for (const k of Object.keys(d)) {
    if (Array.isArray(d[k]) && d[k].length && typeof d[k][0] === 'object') return d[k];
  }
  return [];
}

function customerNoOf(c) {
  return norm(c.customerNo !== undefined ? c.customerNo : (c.customerNumber !== undefined ? c.customerNumber : (c.musteriNo !== undefined ? c.musteriNo : c.id)));
}

function servicesOf(c) {
  return c.services || c.servisler || c.responses || {};
}

function findCustomer(no) {
  const n = norm(no);
  return customers().find(function (c) { return customerNoOf(c) === n; }) || null;
}

function isEntry(o) {
  if (!o || typeof o !== 'object' || Array.isArray(o)) return false;
  const hasStatus = ('http' in o) || ('status' in o) || ('statusCode' in o) || ('httpStatus' in o);
  const hasBody = ('response' in o) || ('body' in o) || ('yanit' in o);
  return hasStatus && hasBody;
}

function entryStatus(e) {
  const s = e.http !== undefined ? e.http : (e.status !== undefined ? e.status : (e.statusCode !== undefined ? e.statusCode : e.httpStatus));
  const n = parseInt(s, 10);
  return isNaN(n) ? 200 : n;
}

function entryBody(e) {
  if (e.response !== undefined) return e.response;
  if (e.body !== undefined) return e.body;
  return e.yanit;
}

function entryDelayMs(e) {
  if (e.delaySeconds !== undefined) return Number(e.delaySeconds) * 1000;
  if (e.delay_seconds !== undefined) return Number(e.delay_seconds) * 1000;
  if (e.delaySec !== undefined) return Number(e.delaySec) * 1000;
  if (e.delayMs !== undefined) return Number(e.delayMs);
  if (e.delay_ms !== undefined) return Number(e.delay_ms);
  if (e.delay !== undefined) return Number(e.delay) * 1000;
  if (e.gecikmeSaniye !== undefined) return Number(e.gecikmeSaniye) * 1000;
  return 0;
}

async function serveEntry(e) {
  const ms = entryDelayMs(e);
  if (ms > 0 && isFinite(ms)) await new Promise(function (r) { setTimeout(r, ms); });
  const body = entryBody(e);
  return jsonResponse(body === undefined ? {} : body, entryStatus(e));
}

function serviceNode(c, service) {
  const s = servicesOf(c);
  return s ? s[service] : undefined;
}

function findCardNode(service, cardNumber) {
  const cn = norm(cardNumber);
  for (const c of customers()) {
    const node = serviceNode(c, service);
    if (node && typeof node === 'object' && !isEntry(node) && node[cn] !== undefined) return node[cn];
  }
  return undefined;
}

function firstCardNumber() {
  for (const c of customers()) {
    const node = serviceNode(c, 'cards.balance');
    if (node && typeof node === 'object' && !isEntry(node)) {
      const keys = Object.keys(node);
      if (keys.length) return keys[0];
    }
  }
  return '';
}

function defaultCustomerNo() {
  const c = customers()[0];
  return c ? customerNoOf(c) : '';
}

async function readFields(request) {
  let body;
  try {
    const text = await request.text();
    if (!text || !text.trim()) return { ok: true, fields: {} };
    body = JSON.parse(text);
  } catch (e) {
    return { ok: false };
  }
  if (!body || typeof body !== 'object') return { ok: true, fields: {} };
  const fields = (body.data && typeof body.data === 'object' && !Array.isArray(body.data)) ? body.data : body;
  return { ok: true, fields: fields };
}

function resolveCustomerNo(v) {
  if (isTemplate(v)) return defaultCustomerNo();
  return norm(v);
}

function resolveCard(v) {
  if (isTemplate(v)) return firstCardNumber();
  return norm(v);
}

async function customerService(service, fields, opts) {
  if (isEmpty(fields.customerNo)) return invalidArgs('customerNo cannot be empty');
  if (opts && opts.extraCheck) {
    const r = opts.extraCheck(fields);
    if (r) return r;
  }
  const no = resolveCustomerNo(fields.customerNo);
  const c = findCustomer(no);
  if (!c) return notFound(service, 'customer not found');
  const node = serviceNode(c, service);
  if (!node || !isEntry(node)) return notFound(service, 'customer not found');
  return serveEntry(node);
}

async function cardService(service, fields) {
  if (isEmpty(fields.cardNumber)) return invalidArgs('card number cannot be empty');
  const cn = resolveCard(fields.cardNumber);
  const node = findCardNode(service, cn);
  if (!node || !isEntry(node)) return notFound(service, 'card not found');
  return serveEntry(node);
}

async function weekService(service, fields) {
  if (isEmpty(fields.cardNumber)) return invalidArgs('card number cannot be empty');
  if (isEmpty(fields.newStatementWeek)) return invalidArgs('newStatementWeek cannot be empty');
  if (isEmpty(fields.statementDay)) return invalidArgs('statementDay cannot be empty');
  const cn = resolveCard(fields.cardNumber);
  const node = findCardNode(service, cn);
  if (!node || typeof node !== 'object') return invalidArgs('card not found');
  let week;
  if (isTemplate(fields.newStatementWeek)) {
    week = Object.keys(node)[0];
  } else {
    week = normWeek(fields.newStatementWeek);
    if (!/^[1-4]$/.test(week)) return invalidArgs('newStatementWeek must be between 1 and 4');
  }
  if (!isTemplate(fields.statementDay) && !/^\d+$/.test(norm(fields.statementDay))) return invalidArgs('statementDay is invalid');
  const entry = node[week];
  if (!entry || !isEntry(entry)) return invalidArgs('newStatementWeek is invalid for this card');
  return serveEntry(entry);
}

function checkAddressType(fields) {
  if (isEmpty(fields.intAddressInfoType)) return invalidArgs('intAddressInfoType cannot be empty');
  if (isTemplate(fields.intAddressInfoType)) return null;
  const t = norm(fields.intAddressInfoType).toUpperCase();
  if (['E', 'P', 'B'].indexOf(t) < 0) return invalidArgs('intAddressInfoType is invalid');
  return null;
}

function checkPdf(fields) {
  if (isEmpty(fields.cardNumber)) return invalidArgs('card number cannot be empty');
  if (isEmpty(fields.currencyType)) return invalidArgs('currencyType cannot be empty');
  if (!isTemplate(fields.currencyType) && ['TL', 'USD', 'EUR', 'GBP'].indexOf(norm(fields.currencyType).toUpperCase()) < 0) return invalidArgs('currencyType is invalid');
  if (isEmpty(fields.statementDate)) return invalidArgs('statementDate cannot be empty');
  if (!isTemplate(fields.statementDate) && !/^\d{2}\.\d{2}\.\d{4}$/.test(norm(fields.statementDate))) return invalidArgs('statementDate is invalid');
  if (isEmpty(fields.emailAddress)) return invalidArgs('emailAddress cannot be empty');
  return null;
}

async function handleBank(request, env) {
  const url = new URL(request.url);
  const path = url.pathname;
  if (request.method === 'OPTIONS') {
    return new Response(null, { status: 204, headers: Object.assign({}, JSON_HEADERS, { 'Access-Control-Allow-Methods': 'GET, POST, OPTIONS', 'Access-Control-Allow-Headers': '*' }) });
  }
  if (request.method === 'GET' && (path === '/health' || path === '/')) {
    return jsonResponse({ status: 'ok', services: SERVICES.map(function (s) { return 'POST ' + BASE + s; }) }, 200);
  }
  if (!path.startsWith(BASE)) {
    return jsonResponse({ error: 'not found', paths: SERVICES.map(function (s) { return 'POST ' + BASE + s; }) }, 404);
  }
  const service = path.slice(BASE.length);
  if (SERVICES.indexOf(service) < 0) {
    return jsonResponse({ error: 'not found', paths: SERVICES.map(function (s) { return 'POST ' + BASE + s; }) }, 404);
  }
  if (request.method !== 'POST') {
    return jsonResponse({ error: 'method not allowed', allowed: 'POST' }, 405);
  }
  const parsed = await readFields(request);
  if (!parsed.ok) return invalidArgs('request body is not valid JSON');
  const f = parsed.fields || {};
  try {
    switch (service) {
      case 'cards.list': return await customerService('cards.list', f);
      case 'cards.balance': return await cardService('cards.balance', f);
      case 'statement.week.get': return await cardService('statement.week.get', f);
      case 'statement.week.decide': return await weekService('statement.week.decide', f);
      case 'statement.week.change': return await weekService('statement.week.change', f);
      case 'contact.email.get': return await customerService('contact.email.get', f, { extraCheck: checkAddressType });
      case 'statement.pdf.send': return await customerService('statement.pdf.send', f, { extraCheck: checkPdf });
    }
  } catch (e) {
    return technicalError();
  }
  return jsonResponse({ error: 'not found' }, 404);
}
